solutionCode:
open class Subsystem(val name: String)

class DriveSubsystem(val motorCount: Int) : Subsystem("Drivetrain")

class ShooterSubsystem(val launchSpeed: Double) : Subsystem("Shooter")

fun describeSubsystem(sub: Subsystem): String {
    if (sub is DriveSubsystem) {
        return "Drive system with ${sub.motorCount} motors"
    } else if (sub is ShooterSubsystem) {
        return "Shooter with speed ${sub.launchSpeed}"
    } else {
        return "Generic subsystem: ${sub.name}"
    }
}

testCode:
import org.junit.Test
import org.junit.Assert

class Tests {
    @Test
    fun testDriveSubsystem() {
        val result = describeSubsystem(DriveSubsystem(4))
        Assert.assertEquals("Drive system with 4 motors", result)
    }

    @Test
    fun testShooterSubsystem() {
        val result = describeSubsystem(ShooterSubsystem(0.85))
        Assert.assertEquals("Shooter with speed 0.85", result)
    }

    @Test
    fun testGenericSubsystem() {
        val result = describeSubsystem(Subsystem("Intake"))
        Assert.assertEquals("Generic subsystem: Intake", result)
    }

    @Test
    fun testDifferentMotorCount() {
        val result = describeSubsystem(DriveSubsystem(6))
        Assert.assertEquals("Drive system with 6 motors", result)
    }
}
